-- 0013_orders_session_id.sql
-- Add session_id to orders and kot_tickets so the kiosk can group multiple
-- order rounds placed by the same table into a single billing session.
-- session_id is the tt_session_id UUID generated by the kiosk on first load
-- (stored in sessionStorage). Nullable so existing rows and POS-created
-- orders are unaffected.

ALTER TABLE orders
  ADD COLUMN IF NOT EXISTS session_id text;

ALTER TABLE kot_tickets
  ADD COLUMN IF NOT EXISTS session_id text;

CREATE INDEX IF NOT EXISTS orders_session_id_idx ON orders (session_id)
  WHERE session_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS kot_tickets_session_id_idx ON kot_tickets (session_id)
  WHERE session_id IS NOT NULL;
